import itertools

def main():
    n, a, b = map(int, input().split())
    frames = [a] * 4 + [b] * 2

    best_answer = 6

    for perm in itertools.permutations(frames):
        count, leftover = 0, 0
        for length in perm:
            if leftover < length:
                count += 1
                leftover = n
            leftover -= length
        if count < best_answer:
            best_answer = count

    print(best_answer)

if __name__ == "__main__":
    main()

